<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require BASE_PATH.'/app/AdminUi.php';$user=Auth::requireLogin();Auth::requirePermission('settings.manage');if(($user['role']??'')!=='super_admin'){http_response_code(403);exit('هذه الصفحة لمدير النظام الرئيسي فقط.');}$pdo=Database::connection();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();try{$roleId=(int)($_POST['role_id']??0);$selected=array_map('intval',$_POST['permissions']??[]);if(!$roleId)throw new RuntimeException('اختر الدور.');$q=$pdo->prepare('SELECT role_key FROM roles WHERE id=?');$q->execute([$roleId]);$key=$q->fetchColumn();if(!$key||$key==='super_admin')throw new RuntimeException('لا يمكن تعديل صلاحيات مدير النظام الرئيسي من هذه الصفحة.');$pdo->beginTransaction();$pdo->prepare('DELETE FROM role_permissions WHERE role_id=?')->execute([$roleId]);$ins=$pdo->prepare('INSERT INTO role_permissions(role_id,permission_id) VALUES(?,?)');foreach(array_unique($selected) as $pid)$ins->execute([$roleId,$pid]);$pdo->commit();admin_log($pdo,$user,'role.permissions_updated','role',$roleId,'تحديث صلاحيات الدور '.$key);redirect('/admin/roles.php?saved=1');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}$roles=$pdo->query('SELECT id,role_key,name FROM roles ORDER BY id')->fetchAll();$permissions=$pdo->query('SELECT id,permission_key,name FROM permissions ORDER BY id')->fetchAll();$selectedRole=(int)($_GET['role']??($roles[0]['id']??0));$q=$pdo->prepare('SELECT permission_id FROM role_permissions WHERE role_id=?');$q->execute([$selectedRole]);$selected=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));admin_page_start('الأدوار والصلاحيات',$user);if($error)echo '<p class="notice danger">'.e($error).'</p>';if(isset($_GET['saved']))echo '<p class="notice">تم تحديث الصلاحيات.</p>';echo '<section class="panel"><form method="get" class="inline"><label>الدور<select name="role">';foreach($roles as $r)echo '<option value="'.(int)$r['id'].'" '.($selectedRole===(int)$r['id']?'selected':'').'>'.e($r['name']).'</option>';echo '</select></label><button class="btn-sm">عرض</button></form></section><section class="panel"><form method="post"><input type="hidden" name="_csrf" value="'.e(Security::csrf()).'"><input type="hidden" name="role_id" value="'.$selectedRole.'"><div class="form-grid">';foreach($permissions as $p)echo '<label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="permissions[]" value="'.(int)$p['id'].'" '.(in_array((int)$p['id'],$selected,true)?'checked':'').'>'.e($p['name']).' <small class="muted">'.e($p['permission_key']).'</small></label>';echo '</div><p><button class="btn btn-primary">حفظ الصلاحيات</button></p></form></section>';admin_page_end();
